<?php
require_once __DIR__ . '/includes/bootstrap.php';
require_login();
if (!is_admin()) { header('Location: home.php'); exit; }
$users = (int)$conn->query('SELECT COUNT(*) FROM users')->fetchColumn();
$movies = (int)$conn->query('SELECT COUNT(*) FROM movies')->fetchColumn();
$bookings = (int)$conn->query('SELECT COUNT(*) FROM bookings')->fetchColumn();
$pending = (int)$conn->query("SELECT COUNT(*) FROM bookings WHERE is_approved <> 'true'")->fetchColumn();
$latest = $conn->query("SELECT b.id,b.nr_tickets,b.date,b.time,b.is_approved,m.movie_name,u.username FROM bookings b JOIN movies m ON m.id=b.movie_id JOIN users u ON u.id=b.user_id ORDER BY b.id DESC LIMIT 8")->fetchAll();
page_start('Dashboard','dashboard.php');
?>
<div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="stat-card"><div class="d-flex justify-content-between"><span class="stat-label">Përdorues</span><span class="stat-icon">♙</span></div><div class="stat-value"><?= $users ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="d-flex justify-content-between"><span class="stat-label">Filma</span><span class="stat-icon">▣</span></div><div class="stat-value"><?= $movies ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="d-flex justify-content-between"><span class="stat-label">Rezervime</span><span class="stat-icon">▤</span></div><div class="stat-value"><?= $bookings ?></div></div></div><div class="col-6 col-xl-3"><div class="stat-card"><div class="d-flex justify-content-between"><span class="stat-label">Në pritje</span><span class="stat-icon">◷</span></div><div class="stat-value"><?= $pending ?></div></div></div></div>
<section class="panel mb-4"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-3"><h2 class="section-title mb-0">Rezervimet e fundit</h2><a class="btn btn-sm btn-outline-secondary" href="bookings.php">Shiko të gjitha</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Filmi</th><th>Klienti</th><th>Bileta</th><th>Data</th><th>Ora</th><th>Statusi</th></tr></thead><tbody><?php foreach($latest as $b): ?><tr><td class="fw-semibold"><?= e($b['movie_name']) ?></td><td><?= e($b['username']) ?></td><td><?= (int)$b['nr_tickets'] ?></td><td><?= e($b['date']) ?></td><td><?= e($b['time']) ?></td><td><span class="badge-status <?= $b['is_approved']==='true'?'status-true':'status-pending' ?>"><?= $b['is_approved']==='true'?'Aprovuar':'Në pritje' ?></span></td></tr><?php endforeach; ?><?php if(!$latest): ?><tr><td colspan="6" class="empty-state">Nuk ka ende rezervime.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if(is_admin()): ?><section class="panel"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="section-title mb-0">Përdoruesit</h2><span class="text-secondary small">Administrimi i llogarive</span></div><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Emri</th><th>Username</th><th>Email</th><th>Roli</th><th>Veprimi</th></tr></thead><tbody><?php foreach($conn->query('SELECT id,emri,username,email,is_admin FROM users ORDER BY id DESC') as $u): ?><tr><td><?= (int)$u['id'] ?></td><td><?= e($u['emri']) ?></td><td><?= e($u['username']) ?></td><td><?= e($u['email']) ?></td><td><?= $u['is_admin']==='true'?'Administrator':'Klient' ?></td><td><?php if((int)$u['id'] !== (int)$_SESSION['id']): ?><a class="btn btn-sm btn-outline-danger" href="deleteUsers.php?id=<?= (int)$u['id'] ?>" onclick="return confirm('A dëshiron ta fshish këtë përdorues?')">Fshij</a><?php else: ?><span class="text-secondary small">Llogaria jote</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php page_end(); ?>
